// Support both n8n ($json) and standalone execution
function calculateKeywordDensity(article, keyword) {
  // #region agent log
  fetch('http://127.0.0.1:7242/ingest/073d303b-1e5c-4ba8-9f85-3c3e3ac9ddfc',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'keyword_density.js:calculateKeywordDensity:entry',message:'Function entry',data:{articleLength:article?article.length:0,keyword:keyword},timestamp:Date.now(),sessionId:'debug-session',runId:'run1',hypothesisId:'A'})}).catch(()=>{});
  // #endregion

  if (!article || !keyword) {
    // #region agent log
    fetch('http://127.0.0.1:7242/ingest/073d303b-1e5c-4ba8-9f85-3c3e3ac9ddfc',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'keyword_density.js:calculateKeywordDensity:early-return',message:'Early return - missing inputs',data:{hasArticle:!!article,hasKeyword:!!keyword},timestamp:Date.now(),sessionId:'debug-session',runId:'run1',hypothesisId:'A'})}).catch(()=>{});
    // #endregion
    return {
      totalWords: 0,
      keywordCount: 0,
      keywordDensityPercent: 0
    };
  }

  const words = article.toLowerCase().split(/\s+/).filter(Boolean);
  const total = words.length;
  const count = words.filter(w => w.includes(keyword.toLowerCase())).length;
  const density = Number(((count / total) * 100).toFixed(2));

  // #region agent log
  fetch('http://127.0.0.1:7242/ingest/073d303b-1e5c-4ba8-9f85-3c3e3ac9ddfc',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'keyword_density.js:calculateKeywordDensity:exit',message:'Function exit with results',data:{totalWords:total,keywordCount:count,keywordDensityPercent:density},timestamp:Date.now(),sessionId:'debug-session',runId:'run1',hypothesisId:'A'})}).catch(()=>{});
  // #endregion

  return {
    totalWords: total,
    keywordCount: count,
    keywordDensityPercent: density
  };
}

// n8n execution context
if (typeof $json !== 'undefined') {
  // #region agent log
  fetch('http://127.0.0.1:7242/ingest/073d303b-1e5c-4ba8-9f85-3c3e3ac9ddfc',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'keyword_density.js:n8n-path',message:'Executing in n8n context',data:{hasOptimizedArticle:'optimized_article_markdown' in ($json||{}),hasPrimaryKeyword:'primary_keyword' in ($json||{})},timestamp:Date.now(),sessionId:'debug-session',runId:'run1',hypothesisId:'A'})}).catch(()=>{});
  // #endregion
  const article = $json.optimized_article_markdown || "";
  const keyword = $json.primary_keyword || "";
  return calculateKeywordDensity(article, keyword);
} 
// Standalone Node.js execution
else if (typeof require !== 'undefined' && require.main === module) {
  // #region agent log
  fetch('http://127.0.0.1:7242/ingest/073d303b-1e5c-4ba8-9f85-3c3e3ac9ddfc',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'keyword_density.js:standalone-path',message:'Executing in standalone mode',data:{argvLength:process.argv.length},timestamp:Date.now(),sessionId:'debug-session',runId:'run1',hypothesisId:'A'})}).catch(()=>{});
  // #endregion
  const args = process.argv.slice(2);
  if (args.length >= 2) {
    const article = args[0];
    const keyword = args[1];
    const result = calculateKeywordDensity(article, keyword);
    console.log(JSON.stringify(result, null, 2));
    process.exit(0);
  } else {
    console.error('Usage: node keyword_density.js "<article>" "<keyword>"');
    process.exit(1);
  }
}
