function countSentences(text) {
  const matches = text.match(/[.!?]/g);
  return matches ? matches.length : 1;
}

function countSyllables(word) {
  const m = word.toLowerCase().match(/[aeiouy]+/g);
  return m ? m.length : 1;
}

function fleschReadingEase(text) {
  // #region agent log
  fetch('http://127.0.0.1:7242/ingest/073d303b-1e5c-4ba8-9f85-3c3e3ac9ddfc',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'readability_check.js:fleschReadingEase:entry',message:'Flesch calculation entry',data:{textLength:text?text.length:0},timestamp:Date.now(),sessionId:'debug-session',runId:'run1',hypothesisId:'B'})}).catch(()=>{});
  // #endregion

  const words = text.split(/\s+/).filter(Boolean);
  const numWords = words.length || 1;
  const numSentences = countSentences(text);
  const numSyllables = words.reduce((sum, w) => sum + countSyllables(w), 0);

  const ASL = numWords / numSentences;
  const ASW = numSyllables / numWords;

  const score = 206.835 - 1.015 * ASL - 84.6 * ASW;

  // #region agent log
  fetch('http://127.0.0.1:7242/ingest/073d303b-1e5c-4ba8-9f85-3c3e3ac9ddfc',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'readability_check.js:fleschReadingEase:exit',message:'Flesch calculation exit',data:{numWords,numSentences,numSyllables,ASL,ASW,score},timestamp:Date.now(),sessionId:'debug-session',runId:'run1',hypothesisId:'B'})}).catch(()=>{});
  // #endregion

  return score;
}

